css_variables:
:root {
  --color-primary: #4F46E5;
  --color-secondary: #4338CA;
  --color-accent: #22D3EE;
  --color-highlight: #F3F4FF;
  --color-bg: #FFFFFF;
  --color-text: #0B1220;
  --color-text-muted: #6B7280;
  --color-border: #E5E7EB;
  --font-heading: 'Barlow Condensed', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-body: 'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-size-display: 60px;
  --font-size-h1: 42px;
  --font-size-h2: 32px;
  --font-size-h3: 24px;
  --font-size-h4: 18px;
  --font-size-body: 16px;
  --font-size-small: 13px;
  --font-weight-heading: 700;
  --font-weight-body: 400;
  --line-height-body: 1.7;
  --border-radius: 8px;
  --shadow-card: 0 2px 8px rgba(0,0,0,0.08), 0 8px 20px rgba(79,70,229,0.10);
}
